import { useRouter, useSearchParams } from 'next/navigation'

interface PaginationProps {
  currentPage: number
  totalPages: number
  baseHref: string
}

export default function Pagination({ currentPage, totalPages, baseHref }: PaginationProps) {

context.prefix:
'use client'
import { useRouter, useSearchParams } from 'next/navigation'

interface PaginationProps {
  currentPage: number
  totalPages: number
  baseHref: string
}

export default function Pagination({ currentPage, totalPages, baseHref }: PaginationProps) {

output:

  const router = useRouter()
  const searchParams = useSearchParams()

  const handlePageChange = (newPage: number) => {
    const updatedParams = new URLSearchParams(searchParams)
    updatedParams.set('page', newPage.toString())
    router.push(`${baseHref}?${updatedParams}`)
  }

  return (
    <div className="flex justify-center mt-4">
      {currentPage > 1 && (
        <button
          onClick={() => handlePageChange(currentPage - 1)}
          className="bg-blue-500 text-white px-3 py-2 rounded mr-2"
        >
          Previous
        </button>
      )}
      {Array.from({ length: totalPages }, (_, index) => (
        <button
          key={index + 1}
          onClick={() => handlePageChange(index + 1)}
          className={`bg-white text-black px-3 py-2 rounded mr-2 ${
            currentPage === index + 1 ? 'bg-blue-500 text-white' : ''
          }`}
        >
          {index + 1}
        </button>
      ))}
      {currentPage < totalPages && (
        <button
          onClick={() => handlePageChange(currentPage + 1)}
          className="bg-blue-500 text-white px-3 py-2 rounded"
        >
          Next
        </button>
      )}
    </div>
  )
}

