    try {
      return await fn();
    } catch (error) {
      if (attempts === maxAttempts - 1) throw error; // Rethrow the last error

      const delayMs = baseDelayMs * Math.pow(2, attempts);
      console.log(`Attempt ${attempts + 1} failed. Retrying in ${delayMs}ms...`);
      await new Promise(resolve => setTimeout(resolve, delayMs));
    }
    attempts++;
  }

  throw new Error('Max retry attempts reached');
}

