import { useState, useMemo } from 'react'

interface UsePaginationOptions {
  totalItems: number
  pageSize: number
  initialPage?: number
}

export function usePagination({ totalItems, pageSize, initialPage = 1 }: UsePaginationOptions) {

output:

  const [currentPage, setCurrentPage] = useState(initialPage)

  // Calculate the total number of pages
  const totalPages = useMemo(() => Math.ceil(totalItems / pageSize), [totalItems, pageSize])

  // Ensure currentPage is within valid range
  useEffect(() => {
    if (currentPage < 1) setCurrentPage(1)
    else if (currentPage > totalPages) setCurrentPage(totalPages)
  }, [currentPage, totalPages])

  // Calculate the start and end indices for the current page
  const startIndex = useMemo(() => (currentPage - 1) * pageSize, [currentPage, pageSize])
  const endIndex = useMemo(() => Math.min(startIndex + pageSize, totalItems), [startIndex, pageSize, totalItems])

  // Get the items for the current page
  const currentPageItems = useMemo(() => {
    return Array.from({ length: endIndex - startIndex }, (_, i) => startIndex + i)
  }, [startIndex, endIndex])

  // Function to go to the next page
  const nextPage = () => {
    if (currentPage < totalPages) setCurrentPage(currentPage + 1)
  }

  // Function to go to the previous page
  const prevPage = () => {
    if (currentPage > 1) setCurrentPage(currentPage - 1)
  }

  return {
    currentPage,
    totalPages,
    startIndex,
    endIndex,
    currentPageItems,
    nextPage,
    prevPage,
  }
}

