    where: {
      email: data.email,
    },
  })

  if (existingUser) {
    throw new Error('Email already in use')
  }

  // Hash the password
  const hashedPassword = await bcrypt.hash(data.password, 10)

  // Create the user
  const user = await prisma.user.create({
    data: {
      email: data.email,
      name: data.name,
      password: hashedPassword,
    },
  })

  return user
}

